from rules import solve_versions


def solve(data):
    return solve_versions(data)

import copy


def solve_versions(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    package_names = sorted(packages)
    best_score = None
    best_versions = None

    def satisfies(version, ranges):
        return all(low <= version <= high for low, high in ranges)

    def has_path(graph, start, target):
        stack = [start]
        seen = set()
        while stack:
            node = stack.pop()
            if node == target:
                return True
            if node in seen:
                continue
            seen.add(node)
            stack.extend(graph.get(node, ()))
        return False

    def search(assigned, constraints, graph):
        nonlocal best_score, best_versions
        pending = sorted(name for name in constraints if name not in assigned)
        if not pending:
            score = tuple(assigned[name]['version'] if name in assigned else -1
                          for name in package_names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {name: row['version'] for name, row in assigned.items()}
            return

        name = pending[0]
        for row in packages.get(name, []):
            version = row['version']
            if not satisfies(version, constraints[name]):
                continue
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue

            next_assigned = assigned.copy()
            next_assigned[name] = row
            next_constraints = copy.deepcopy(constraints)
            next_graph = copy.deepcopy(graph)
            next_graph.setdefault(name, set())
            feasible = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                next_graph.setdefault(target, set())
                if has_path(next_graph, target, name):
                    feasible = False
                    break
                next_graph[name].add(target)
                next_constraints.setdefault(target, []).append((dep['min'], dep['max']))
                if target in next_assigned and not satisfies(
                        next_assigned[target]['version'], next_constraints[target]):
                    feasible = False
                    break

            if feasible:
                search(next_assigned, next_constraints, next_graph)

    initial_constraints = {name: [(bounds[0], bounds[1])]
                           for name, bounds in roots.items()}
    search({}, initial_constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
